extern f64 kU32ToDoubleBias;
extern s32 gAudioOutputRate;

/* Converts a rate to a 12-bit fixed-point ratio relative to the audio output rate. */ s32 convertRateToFixedPitch(s32 rate) {
    f32 scaled;
    f64 rateAsDouble;
    s32 result;

    rateAsDouble = (f64) rate;
    if (rate < 0) {
        rateAsDouble += kU32ToDoubleBias;
    }
    scaled = ((f32) rateAsDouble * 4096.0f) / (f32) gAudioOutputRate;
    result = (u32) scaled;
    return result;
}
